(function(){'use strict';
const D=window.NK_DATA,C=window.NK,KEY='naehrstoff-kompass:v1',NS=D.nutrients,KEYS=NS.map(n=>n.key),byId=new Map(D.foods.map(f=>[f.id,f])),MEALS=['Frühstück','Mittagessen','Abendessen','Snacks'];
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=(v,d=1)=>v===null||v===undefined?'—':new Intl.NumberFormat('de-CH',{maximumFractionDigits:d}).format(v),uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2),copy=C.clone;
let state=C.initial(),storageProblem='',route='today',date=C.dateKey(),search='',filter='all',recipeSearch='',nutrientTab='vitamin',historyDays=7,completeOnly=false,draft=null,dirty=false,modal=null,undo=null,toastTimer,installPrompt=null,lastFocus=null,mutationBusy=false,saveChain=Promise.resolve(),reportOptions=null;
try{const raw=(window.NK_STORE||localStorage).getItem(KEY);if(raw)state=C.validateState(JSON.parse(raw),KEYS);}catch(e){storageProblem='Gespeicherte Daten konnten nicht gelesen werden. Sie werden nicht automatisch überschrieben. Nutze «Rohdaten sichern» im Profil, bevor du den Speicher zurücksetzt.';}
let storageBlocked=!!storageProblem;
const iconPaths={compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2.5 5.5L8 16l2.5-5.5Z"/>',today:'<rect x="4" y="4" width="16" height="16" rx="4"/><path d="M4 10h16M9 4v16"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',recipes:'<path d="M5 5h14v15H5zM8 2v5m4-5v5m4-5v5M9 12h6m-6 4h4"/>',history:'<path d="M4 4v16h16M8 15v-4m5 4V7m5 8v-6"/>',profile:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',plus:'<path d="M12 5v14M5 12h14"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',chevron:'<path d="m9 5 7 7-7 7"/>',left:'<path d="m15 5-7 7 7 7"/>',leaf:'<path d="M20 4C8 1 2 8 5 15s16 3 15-11ZM4 21 15 10"/>',edit:'<path d="m14 5 5 5M4 20l5-1L21 7l-4-4L5 15Z"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',star:'<path d="m12 3 2.8 5.7L21 9.6l-4.5 4.4 1.1 6.2-5.6-2.9-5.6 2.9L7.5 14 3 9.6l6.2-.9Z"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5"/>',check:'<path d="m5 12 4 4L19 6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M15 8V3H3v13h5"/>',bowl:'<path d="M3 11h18a9 9 0 0 1-18 0Zm4 9h10M8 7V3m4 4V2m4 5V3"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>',moon:'<path d="M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12Z"/>',bolt:'<path d="m13 2-8 12h6l-1 8 9-12h-6Z"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>'};
const ico=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${iconPaths[n]||iconPaths.leaf}</svg>`;
const btn=(text,action,style='',attrs='')=>`<button type="button" class="button ${style}" data-action="${action}" ${attrs}>${text}</button>`;
const ib=(name,action,label,attrs='')=>`<button type="button" class="icon-btn flat" data-action="${action}" aria-label="${esc(label)}" title="${esc(label)}" ${attrs}>${ico(name)}</button>`;
const numField=(id,label,value='',help='',attrs='')=>`<div class="field"><label for="${id}">${label}</label><input id="${id}" name="${id}" inputmode="decimal" value="${esc(value??'')}" ${attrs}>${help?`<small>${help}</small>`:''}</div>`;
const options=(items,value)=>items.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('');
const P=window.NK_PIECES,U=window.NK_CUPS;
const unitOptions=f=>[...P.units(f),...U.units];
const describeAmount=(f,q,u,d)=>U.isCup(u)?U.describe(f,q,u,d):P.describe(f,U.amount(q),u);
const M=window.NK_MEASURES;
const sourceFood=f=>({id:f.id,name:f.name,synonyms:f.synonyms||'',category:f.category||'',density:f.density??null,basis:f.basis,source:f.source||'Eigene Angaben',kind:f.kind||'custom',n:copy(f.n),q:copy(f.q||{}),sourceUrl:f.sourceUrl||null,cup:f.cup?copy(f.cup):null,portion:f.portion?copy(f.portion):null,...(f.shared?{shared:copy(f.shared)}:{})});
const food=id=>state.foods.find(f=>f.id===id)||byId.get(id)||window.NK_SHARED?.foods().find(f=>f.id===id);
const recipes=()=>[...state.recipes,...(window.NK_SHARED?.recipes()||[])];
const recipe=id=>recipes().find(r=>r.id===id);
function sharedInfo(){return '<div class="shared-note"><b>Gemeinsamer Haushaltskatalog</b><span data-shared-status>'+esc(window.NK_SHARED?.status||'Wird geladen …')+'</span><button class="muted-link" type="button" data-action="shared-refresh">Katalog aktualisieren</button><small>Produkte und Gerichte aller Profile; gegessene Mengen und Ziele bleiben getrennt. Fremde Vorlagen werden beim Bearbeiten als eigene Variante gespeichert.</small></div>';}
async function persist(next){
 if(storageBlocked)throw Error(storageProblem||'Bitte vorhandene Rohdaten sichern oder die Seite neu laden.');
 try{const result=await (window.NK_STORE||localStorage).setItem(KEY,JSON.stringify(next),JSON.stringify(state));state=result?C.validateState(JSON.parse(result),KEYS):next;storageProblem='';}
 catch(e){if(e.bufferedRaw)state=C.validateState(JSON.parse(e.bufferedRaw),KEYS);storageProblem=e.name==='QuotaExceededError'?'Die lokale Sicherung hat keinen Platz mehr. Bitte exportieren und die Verbindung zum Server prüfen.':e.message||'Speichern fehlgeschlagen. Bitte erneut versuchen; die Eingabe bleibt geöffnet.';throw Error(storageProblem);}
}
async function change(fn){const job=saveChain.then(async()=>{const next=copy(state);fn(next);await persist(next);});saveChain=job.catch(()=>{});return job;}
async function acknowledgeReleases(version,expectedId){
 const R=window.NK_RELEASE_CORE,H=window.NK_HOUSEHOLD;
 if(!R.normalize(version)||R.compare(version,window.NK_DEVICE.version)>0)throw Error('Ungültiger Release-Stand.');
 if(!H?.authenticated||H.id!==expectedId)throw Error('Das aktive Profil wurde gewechselt. Bitte erneut öffnen.');
 if(mutationBusy)throw Error('Bitte warten, bis der laufende Speichervorgang abgeschlossen ist.');
 mutationBusy=true;try{await change(s=>{if(H.id!==expectedId)throw Error('Profilwechsel: Lesestand nicht gespeichert.');s.profile.releaseNotesSeen=R.highest(s.profile.releaseNotesSeen,version);});document.dispatchEvent(new Event('nk-release-acknowledged'));}finally{mutationBusy=false;}
}
async function respondDayReview(day,complete,expectedId,entrySignature){
 const H=window.NK_HOUSEHOLD,R=window.NK_DAY_REVIEW_CORE;
 if(!H?.authenticated||H.id!==expectedId)throw Error('Das Profil wurde gewechselt. Bitte erneut öffnen.');
 if(typeof complete!=='boolean'||!C.validDate(day)||day!==R.previousDay(C.dateKey()))throw Error('Der Kalendertag hat gewechselt. Bitte die neue Tagesübersicht öffnen.');
 if(mutationBusy)throw Error('Bitte den laufenden Speichervorgang abwarten.');
 mutationBusy=true;
 try{await change(s=>{
  if(H.id!==expectedId)throw Error('Profilwechsel: Es wurde kein Häkchen gesetzt.');
  if(day!==R.previousDay(C.dateKey()))throw Error('Der Kalendertag hat gewechselt. Bitte erneut prüfen.');
  if(!C.dayEntries(s,day).length)throw Error('Für diesen Tag sind keine Einträge mehr vorhanden.');
  if(R.signature(s,day,window.NK_SYNC.stable)!==entrySignature)throw Error('Die Einträge wurden zwischenzeitlich geändert. Bitte nochmals prüfen.');
  if(complete)s.days[day]={...s.days[day],complete:true};
  s.profile.dayReviewThrough=R.highest(s.profile.dayReviewThrough,day);
 });
 render();document.dispatchEvent(new Event('nk-day-reviewed'));
 if(complete)notify('Vortag als vollständig protokolliert markiert.');
 }finally{mutationBusy=false;}
}
function openDay(day){if(!C.validDate(day))throw Error('Ungültiges Datum.');if(window.NK_APP.hasDraft||window.NK_DEVICE?.hasUnsavedForm())throw Error('Bitte offene Eingaben zuerst speichern.');date=day;nav('today');}
function notify(text,allowUndo=false){const t=$('#toast');t.innerHTML=`<span>${esc(text)}</span>${allowUndo?'<button data-action="undo">Rückgängig</button>':''}`;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),allowUndo?12000:4800);}
async function removeWithUndo(fn,text){const old=copy(state);await change(fn);undo=old;render();notify(text,true);}
function nav(to){if(route==='editor'&&dirty&&to!=='editor'&&!confirm('Ungespeicherte Änderungen am Gericht verwerfen?'))return;route=to;render();window.scrollTo({top:0,behavior:'instant'});}
function diary(){return C.dayEntries(state,date);}function sumToday(){return C.aggregate(diary().map(e=>e.n),KEYS);}function targetSet(){return C.targets(state.profile);}
function val(s,k,d=1){return fmt(s?.[k]?.value,d)+(s?.[k]?.known>0&&s[k].known<s[k].total?'*':'');}
function brand(){return `<div class="brand"><span class="brand-mark">${ico('compass')}</span><span>Nährstoff<small>KOMPASS</small></span></div>`;}
function navItems(){return [['today','today','Heute'],['search','search','Erfassen'],['recipes','recipes','Gerichte'],['history','history','Verlauf'],['reports','history','Reports'],['profile','profile','Profil']].map(([r,i,t])=>`<button class="nav-btn ${(route===r||r==='recipes'&&route==='editor')?'active':''}" data-action="nav" data-route="${r}" ${route===r?'aria-current="page"':''}>${ico(i)}<span>${t}</span></button>`).join('');}
function heading(title,subtitle,extra='',eyebrow='DEIN ERNÄHRUNGSTAGEBUCH'){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="sub">${subtitle}</p></div>${extra}</div>`;}
function render(){const content=route==='today'?todayView():route==='search'?searchView():route==='recipes'?recipesView():route==='editor'?editorView():route==='history'?historyView():route==='reports'?reportsView():profileView();
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<button type="button" class="profile-switch spaced" data-nk="manager">${esc(window.NK_HOUSEHOLD?.name||'Profil')} ▾</button><nav class="side-nav" aria-label="Hauptnavigation">${navItems()}</nav><div class="side-bottom"><div class="privacy-box">${ico('lock')} <b>Dein privater Bereich.</b><br>Passwortgeschützt synchronisiert. Kein Werbetracking.</div><p class="spaced">Version ${window.NK_DEVICE?.version||C.VERSION} · private Web-App<br>Schweizer Datenbasis · BLV 7.1</p></div></aside><header class="mobile-head">${brand()}<button type="button" class="profile-switch" data-nk="manager">${esc(window.NK_HOUSEHOLD?.name||'Profil')} ▾</button></header><div class="workspace"><div class="topline"><span>NÄHRSTOFF-KOMPASS <span class="pill">v${window.NK_DEVICE?.version||C.VERSION}</span></span><span class="status"><span class="status-dot"></span><span data-nk-status>${esc(window.NK_HOUSEHOLD?.status||'Bereit')}</span> &nbsp; · &nbsp; ${fmt(D.foods.length,0)} Lebensmittel</span></div><main id="main" tabindex="-1"><div class="sync-ribbon"><span data-nk-status>${esc(window.NK_HOUSEHOLD?.status||'Bereit')}</span><button type="button" class="muted-link" data-nk="manager">Profile & Sync</button></div>${storageProblem?`<div class="storage-alert" role="alert">${esc(storageProblem)}</div>`:''}${content}</main><div class="footer-note">Berechnete Nährstoffzufuhr, keine Messung deines Versorgungszustands.<br>Referenzwerte sind Orientierung und keine individuelle Diagnose.</div></div><nav class="bottom-nav" aria-label="Mobile Navigation">${navItems()}</nav></div>`;
 if(route==='search')renderSearchResults();if(route==='editor')updateRecipeSummary();if(route==='profile')updateGoalPreview();}
function getReportOptions(){if(!reportOptions)reportOptions={frequency:window.NK_REPORTS.frequency(state.profile),anchor:C.dateKey(),completeOnly:false,filter:'all'};return reportOptions;}
function reportsView(){return window.NK_REPORT_UI.view(state,NS,getReportOptions());}
function dateControl(){return `<div class="date-control">${ib('left','prev-day','Vorheriger Tag')}<label class="screen-reader" for="diary-date">Datum</label><input id="diary-date" type="date" value="${date}">${ib('chevron','next-day','Nächster Tag')}</div>`;}
function metric(s,k,label,unit,hero=false){return window.NK_MACRO_UI.metric(s,k,label,unit,targetSet().values[k],ico(hero?'bolt':k==='protein'?'leaf':'bowl'),hero);}
function todayView(){const s=sumToday(),entries=diary(),readable=new Intl.DateTimeFormat('de-CH',{weekday:'long',day:'numeric',month:'long'}).format(new Date(date+'T12:00:00'));
 return heading('Dein Tag. Im Überblick.',esc(readable),dateControl())+`${!state.profile.age?`<div class="notice compact">${ico('info')} Dein Tagebuch funktioniert sofort. Für passende Referenzwerte ergänze dein <button class="muted-link" data-action="nav" data-route="profile">Profil</button>.</div>`:''}${window.NK_MACRO_UI.banner(state.profile)}${window.NK_REPORT_UI.banner(state)}<div class="summary-grid">${metric(s,'energy','Energie','kcal',true)}${metric(s,'protein','Protein','g')}${metric(s,'carbs','Kohlenhydrate','g')}${metric(s,'fat','Fett','g')}</div><div class="grid two-col"><section><div class="card"><div class="card-head"><h2>Deine Mahlzeiten</h2>${btn(ico('plus')+' Erfassen','nav','','data-route="search"')}</div>${MEALS.map((m,i)=>`<div class="meal-block"><div class="meal-heading"><div class="meal-title"><span>${ico(['sun','bowl','moon','leaf'][i])}</span><h3>${m}</h3></div>${ib('plus','add-meal',m+' hinzufügen',`data-meal="${i}"`)}</div>${entries.filter(e=>e.meal===i).map(e=>`<div class="entry"><div class="entry-main"><div class="entry-name">${esc(e.name)}</div><div class="entry-amount">${esc(e.amountText)}${e.kind==='recipe'?' · eigenes Gericht':''}</div></div><div class="entry-value">${val(e.n,'energy',0)} kcal<small>${val(e.n,'protein')} g Protein</small></div>${ib('more','entry-menu','Eintrag bearbeiten',`data-id="${e.id}"`)}</div>`).join('')||'<div class="empty-meal">Noch kein Eintrag.</div>'}</div>`).join('')}<label class="check"><input id="day-complete" type="checkbox" ${state.days[date]?.complete?'checked':''} ${!entries.length?'disabled':''}><span>Ich habe diesen Tag vollständig protokolliert.<br><span class="tiny">Eine eigene Einschätzung, keine automatische Vollständigkeitsprüfung.</span></span></label></div><div class="card"><div class="card-head"><h2>Deine Küche, gespeichert.</h2>${ico('recipes')}</div><p class="small">Zutaten eingeben, Nährwerte berechnen und dein Gericht jederzeit wiederverwenden oder anpassen.</p>${btn('Eigenes Gericht erstellen '+ico('plus'),'new-recipe','secondary wide')}</div></section><section><div class="card"><div class="card-head"><h2>Nährstoffe im Detail</h2><span class="pill">${entries.length} Einträge</span></div><div class="section-tabs">${[['vitamin','Vitamine'],['mineral','Mineralstoffe'],['macro','Mehr Makros']].map(([v,t])=>`<button class="chip ${nutrientTab===v?'active':''}" data-action="nutrient-tab" data-tab="${v}">${t}</button>`).join('')}</div>${nutrientTable(s,nutrientTab,true)}<p class="tiny spaced">* Bekannte Teilmenge: Für mindestens eine Zutat fehlt ein genauer Wert. «—» bedeutet unbekannt oder noch nicht erfasst, nicht null.</p><p class="tiny">100 % ist ein Vergleichswert, keine Grenze für Verträglichkeit oder Sicherheit.</p></div></section></div>`;}
function nutrientTable(s,group,compare=false){const refs=targetSet().values;
 return NS.filter(n=>n.group===group).map(n=>{const a=s[n.key]||{value:null,known:0,total:0,missing:[]},ref=compare?refs[n.key]:null,pct=ref&&!ref.noPercent&&a.value!==null?100*a.value/ref.value:null;
 return `<div class="nutrient"><div class="nutrient-top"><button class="nutrient-label" data-action="nutrient-info" data-key="${n.key}">${esc(n.label)} ${ico('info')}</button><span class="nutrient-value">${val(s,n.key,n.key==='energy'?0:2)} ${n.unit}</span></div>${pct!==null?`<div class="track" aria-hidden="true"><span style="width:${Math.min(100,pct)}%"></span></div>`:''}<div class="nutrient-note">${ref?`${ref.type==='Eigenes Ziel'?'Eigenes Ziel':'Referenz'} ${fmt(ref.value)} ${n.unit}${pct!==null?' · '+fmt(pct,0)+' %'+(a.known<a.total?' der bekannten Teilmenge':''):''}${ref.noPercent?' · kein direkter %-Vergleich':''}`:!n.available?'Nicht im BLV-Download enthalten':a.total?'Kein automatischer Referenzvergleich':'Noch keine Zufuhr erfasst'}${a.total&&a.known<a.total?`<br>Genaue Angabe für ${a.known}/${a.total} Zutaten${a.known?' · bekannte Teilmenge':''}`:''}</div></div>`;}).join('');}
function clean(s){return String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ß/g,'ss');}
function findFoods(q,mode='all'){
 let all=[...state.foods,...D.foods,...(window.NK_SHARED?.foods()||[])];if(mode==='favorites')all=all.filter(f=>state.favorites.includes(f.id));if(mode==='custom')all=[...state.foods,...(window.NK_SHARED?.foods()||[])];
 const terms=clean(q).trim().split(/\s+/).filter(Boolean);if(terms.length)return window.NK_FOOD_SEARCH.select(all,q);
 if(!terms.length&&mode==='all'){const preferred=['Haferflocken','Banane','Apfel','Kartoffel, geschält, gedämpft','Hühnerei, ganz, festgekocht','Poulet','Reis','Milch','Broccoli','Olivenöl'];all.sort((a,b)=>{const score=f=>state.recent.includes(f.id)?-1000+state.recent.indexOf(f.id):preferred.findIndex(x=>f.name.startsWith(x))>=0?preferred.findIndex(x=>f.name.startsWith(x)):100;return score(a)-score(b)||a.name.localeCompare(b.name,'de');});}
 else if(terms.length)all.sort((a,b)=>(clean(a.name).startsWith(clean(q))?0:1)-(clean(b.name).startsWith(clean(q))?0:1)||a.name.localeCompare(b.name,'de'));
 return all;
}
function foodRows(arr,mode='log'){return arr.map(f=>`<div class="food-row"><button class="food-open" data-action="food-pick" data-id="${esc(f.id)}" data-mode="${mode}"><span class="food-glyph">${ico('leaf')}</span><span class="food-label"><strong>${esc(f.name)}</strong><small>${f.shared?'Von '+esc(f.shared.ownerName):f.kind==='custom'?'Eigenes Produkt':esc(f.category.split('/')[0])} · pro 100 ${f.basis}${f.portion?' · '+esc(P.label(f)):''}${f.cup?' · '+esc(U.label(f)):''}</small></span><span class="food-side">${fmt(f.n.energy,0)} kcal<small>${fmt(f.n.protein)} g Protein</small></span></button><button class="favorite ${state.favorites.includes(f.id)?'on':''}" data-action="favorite" data-id="${esc(f.id)}" aria-label="${state.favorites.includes(f.id)?'Favorit entfernen':'Als Favorit speichern'}">${ico('star')}</button></div>`).join('');}
function searchView(){return heading('Was hast du gegessen?','Suche ein Lebensmittel oder hinterlege ein eigenes Produkt.','<div class="actions"><button type="button" class="button" data-nk-scan>Produkt scannen</button>'+btn(ico('plus')+' Eigenes Produkt','new-food','secondary')+'</div>')+`<div class="searchbox">${ico('search')}<label class="screen-reader" for="food-search">Lebensmittel suchen</label><input type="search" id="food-search" placeholder="Zum Beispiel Kartoffel, Haferflocken, Milch …" value="${esc(search)}" autocomplete="off"></div><div class="chips">${[['all','Alle Lebensmittel'],['favorites','Favoriten'],['custom','Unser Haushalt']].map(([v,t])=>`<button class="chip ${filter===v?'active':''}" data-action="filter" data-filter="${v}">${t}</button>`).join('')}${btn(ico('recipes')+' Meine Gerichte','nav','ghost','data-route="recipes"')}</div><p class="small">BLV 7.1 · ${fmt(D.foods.length,0)} hinterlegte Lebensmittel. Bitte den passenden Zustand wählen: roh, gekocht oder zubereitet.</p>${sharedInfo()}<div id="search-results"></div>`;}
function renderSearchResults(){const out=$('#search-results');if(!out)return;const arr=findFoods(search,filter);out.innerHTML=`<div class="search-count">${arr.length} Treffer${arr.length>75?' · die ersten 75 angezeigt':''}</div>${arr.length?`<div class="food-list">${foodRows(arr.slice(0,75))}</div>`:`<div class="card empty"><div class="empty-icon">${ico('search')}</div><h3>Hier ist noch nichts dabei.</h3><p>Versuche einen allgemeineren Suchbegriff oder erfasse das Produkt anhand seiner Packung.</p>${btn('Eigenes Produkt anlegen','new-food')}</div>`}`;}
function recipesView(){const list=recipes().filter(r=>clean(r.name).includes(clean(recipeSearch)));return heading('Deine Gerichte. Deine Varianten.','Einmal zusammenstellen. Immer wieder einfach erfassen.','<div class="actions">'+btn('Rezept hineinkopieren','paste-recipe','secondary')+btn(ico('plus')+' Neues Gericht','new-recipe')+'</div>')+`<div class="searchbox">${ico('search')}<input id="recipe-search" type="search" aria-label="Gerichte suchen" placeholder="Deine gespeicherten Gerichte suchen …" value="${esc(recipeSearch)}"></div>${sharedInfo()}${!recipes().length?`<div class="card empty"><div class="empty-icon">${ico('recipes')}</div><h3>Dein erstes eigenes Gericht</h3><p>Zum Beispiel Kartoffelbrei: Kartoffeln, Margarine und deine Proteinmilch hinzufügen. Die App berechnet die Nährwerte aus jeder Zutat.</p>${btn(ico('plus')+' Gericht erstellen','new-recipe')}<p class="tiny spaced">Deine Produkte und Gerichte werden für alle Haushaltsprofile verfügbar. Persönliche Einträge bleiben getrennt.</p></div>`:`<div class="recipe-grid">${list.map(r=>{let n=C.recipePortion(r,1,'portion',KEYS);return `<article class="recipe-card"><div class="recipe-symbol">${ico('bowl')}</div><h3>${esc(r.name)}</h3>${r.shared?'<p class="small">Von '+esc(r.shared.ownerName)+' · gemeinsam nutzbar</p>':''}<div class="small">${r.ingredients.length} Zutaten · ${fmt(r.servings)} Portionen${r.finalWeight?' · '+fmt(r.finalWeight)+' g fertig':''}</div><div class="recipe-meta"><div><b>${val(n,'energy',0)}</b>kcal / Portion</div><div><b>${val(n,'protein')} g</b>Protein / Portion</div></div><div class="actions">${btn(ico('plus')+' Erfassen','log-recipe','',`data-id="${r.id}"`)}${ib('edit','edit-recipe','Gericht bearbeiten',`data-id="${r.id}"`)}${ib('copy','duplicate-recipe','Als Variante kopieren',`data-id="${r.id}"`)}${r.shared?'':ib('trash','delete-recipe','Gericht löschen',`data-id="${r.id}"`)}</div></article>`;}).join('')||'<p class="small">Kein passendes Gericht gefunden.</p>'}</div>`}`;}
function newRecipe(r=null,duplicate=false){if(r?.shared)duplicate=true;draft=r?copy(r):{id:uid(),name:'',servings:1,finalWeight:null,ingredients:[],notes:'',version:1};if(duplicate){delete draft.shared;draft.id=uid();draft.name+=' · Variante';draft.version=1;}draft.ingredients=draft.ingredients.map(i=>U.hydrate(P.hydrate(i)));dirty=false;route='editor';render();window.scrollTo(0,0);}
function editorView(){if(!draft){draft={id:uid(),name:'',servings:1,finalWeight:null,ingredients:[],notes:'',version:1};}
 return heading(state.recipes.some(r=>r.id===draft.id)?'Gericht anpassen':'Ein Gericht nach deinem Geschmack.','Zutaten ändern, Varianten speichern und die Nährwerte direkt sehen.',btn(ico('left')+' Meine Gerichte','nav','secondary','data-route="recipes"'),'REZEPTWERKSTATT')+`<div class="grid two-col"><section class="card"><div class="form-grid"><div class="field full"><label for="recipe-name">Name deines Gerichts</label><input id="recipe-name" maxlength="240" placeholder="Zum Beispiel mein Kartoffelbrei" value="${esc(draft.name)}"></div>${numField('recipe-servings','Anzahl Portionen',draft.servings,'Wie viele Portionen ergibt die ganze Zubereitung?')}${numField('recipe-weight','Fertiges Gesamtgewicht · g',draft.finalWeight,'Optional. Wiege das fertige Gericht ohne Gefäss, um Gramm-Portionen zu erfassen.')}</div><div class="form-section"><div class="card-head"><h2>Zutaten</h2><span class="pill">${draft.ingredients.length} Zutaten</span></div><div id="ingredients">${draft.ingredients.map((i,ix)=>`<div class="ingredient-row"><div class="ingredient-name"><span>${esc(i.food.name)}</span>${ib('trash','remove-ingredient','Zutat entfernen',`data-index="${ix}"`)}</div><div class="ingredient-inputs"><input inputmode="decimal" aria-label="Menge für ${esc(i.food.name)}" value="${esc(i.quantity)}" data-ingredient="${ix}" data-field="quantity"><select aria-label="Einheit für ${esc(i.food.name)}" data-ingredient="${ix}" data-field="unit">${options(unitOptions(i.food),i.unit)}</select>${ib('edit','replace-ingredient','Zutat austauschen',`data-index="${ix}"`)}</div><div class="ingredient-cup-info" data-cup-info="${ix}"></div><div class="ingredient-source">${i.food.portion?esc(P.label(i.food))+' · ':''}${esc(i.food.source)} · ${i.food.density||i.density?'Dichte '+fmt(i.density??i.food.density,3)+' g/ml':'Keine Dichte hinterlegt; für Volumenumrechnung in der Zutat ergänzen.'} ${btn('Details','ingredient-details','ghost',`data-index="${ix}"`)}</div></div>`).join('')||'<p class="small">Hier erscheinen deine Zutaten mit ihren Mengen.</p>'}</div>${btn(ico('plus')+' Zutat hinzufügen','ingredient-search','secondary wide')}</div><div class="notice">Für Kartoffelbrei mit <b>250 g fertigem Gewicht</b> gehören die 250 g hier ins Gesamtgewicht – nicht zusätzlich als Zutat. Die Nährstoffe ergeben sich nur aus den tatsächlichen Zutaten.</div><div class="field"><label for="recipe-notes">Notizen · optional</label><textarea id="recipe-notes" maxlength="30000" placeholder="Zubereitung, Alternative, Lieblingsmarke …">${esc(draft.notes)}</textarea></div>${draft.importText?`<details class="details-section"><summary>Hineinkopiertes Originalrezept</summary><textarea readonly aria-label="Originalrezept" class="recipe-original">${esc(draft.importText)}</textarea><p class="tiny">Deine bestätigten Zutaten und Mengen oben werden berechnet, nicht Nährwertbehauptungen aus dem Originaltext.</p></details>`:""}<p class="tiny spaced">Wähle möglichst den tatsächlichen Zubereitungszustand der Zutaten. Zusätzliche Kochverluste werden nicht pauschal geschätzt.</p><div id="recipe-error"></div><div class="sticky-save">${btn(ico('check')+' Gericht speichern','save-recipe')}${btn(ico('copy')+' Als Variante speichern','save-variant','secondary')}</div></section><aside><div class="card recipe-summary"><div class="card-head"><h2>Live berechnet</h2><span class="pill">Deine Zutaten</span></div><div id="recipe-summary"></div></div></aside></div>`;}
function mini(s){return `<div class="summary-mini">${[['energy','Energie','kcal'],['protein','Protein','g'],['carbs','Kohlenhydrate','g'],['fat','Fett','g']].map(([k,l,u])=>`<div><small>${l}</small><strong>${val(s,k,k==='energy'?0:1)} <span>${u}</span></strong></div>`).join('')}</div>`;}
function updateRecipeSummary(){document.querySelectorAll('[data-cup-info]').forEach(el=>{const i=draft?.ingredients[+el.dataset.cupInfo];try{el.textContent=i&&(U.isCup(i.unit)||i.unit==='piece')?describeAmount(i.food,i.quantity,i.unit,i.density):'';}catch(e){el.textContent=e.message;}});const el=$('#recipe-summary');if(!el||!draft)return;try{const total=C.recipeTotal(draft,KEYS),per=C.recipePortion(draft,1,'portion',KEYS),w=C.recipeWeight(draft);el.innerHTML=`${M.recipeEstimated(draft)?'<p class="measure-warning">Einige Zutatenmengen sind Referenzschätzungen. Die berechneten Nährwerte sind entsprechend näherungsweise.</p>':''}<h3>Pro Portion · 1 von ${fmt(C.positive(draft.servings))}</h3>${mini(per)}<p class="tiny spaced">Gesamtes Gericht: ${val(total,'energy',0)} kcal · ${val(total,'protein')} g Protein</p>${draft.finalWeight?`<p class="small">100 g fertig: ${val(C.recipePortion(draft,100,'g',KEYS),'energy',0)} kcal · ${val(C.recipePortion(draft,100,'g',KEYS),'protein')} g Protein</p>`:'<p class="tiny">Für Angaben pro 100 g bitte das fertige Gesamtgewicht eintragen.</p>'}<p class="tiny">${w!==null?'Zutatengewicht rechnerisch: '+fmt(w)+' g.':'Zutatengewicht nicht vollständig berechenbar.'} Nicht automatisch das Gewicht nach dem Kochen.</p><details class="details-section"><summary>Vitamine und Mineralstoffe pro Portion</summary>${nutrientTable(per,'vitamin')}${nutrientTable(per,'mineral')}</details><p class="tiny spaced">* Teilmenge bei unvollständigen Zutatenangaben.</p>`;}catch(e){el.innerHTML=`<div class="empty"><div class="empty-icon">${ico('bowl')}</div><p>${esc(e.message)}</p></div>`;}}
function readDraft(){if(!draft)return;draft.name=$('#recipe-name')?.value??draft.name;draft.servings=$('#recipe-servings')?.value??draft.servings;draft.finalWeight=$('#recipe-weight')?.value||null;draft.notes=$('#recipe-notes')?.value??draft.notes;}
async function saveRecipe(asVariant=false){readDraft();if(!draft.name.trim())throw Error('Bitte deinem Gericht einen Namen geben.');const r=copy(draft);r.name=r.name.trim();r.servings=C.positive(r.servings);r.finalWeight=C.number(r.finalWeight,{optional:true,min:.000001});r.ingredients.forEach(i=>{i.quantity=U.amount(i.quantity);C.factor(i.food,i.quantity,i.unit,i.density);});r.ingredients=r.ingredients.map(i=>U.canonical(P.canonical(i)));C.recipeTotal(r,KEYS);if(asVariant){r.id=uid();r.name+=' · Variante';r.version=1;}else r.version=(state.recipes.find(x=>x.id===r.id)?.version||0)+1;r.updatedAt=new Date().toISOString();await change(s=>{s.recipes=s.recipes.filter(x=>x.id!==r.id);s.recipes.unshift(r);});dirty=false;draft=r;route='recipes';render();notify('Gericht gespeichert. Frühere Einträge bleiben unverändert.');}
function historyView(){const h=C.history(state,date,historyDays,KEYS,completeOnly);const max=Math.max(1,...h.rows.map(x=>x.n.energy.value||0));return heading('Deine Ernährung im Verlauf.','Durchschnitte nur aus Tagen mit Einträgen – leere Tage zählen nicht als null.',dateControl(),'DEIN VERLAUF')+`<div class="chips">${[7,30].map(d=>`<button class="chip ${historyDays===d?'active':''}" data-action="history-period" data-days="${d}">${d} Tage</button>`).join('')}</div><label class="check"><input id="complete-only" type="checkbox" ${completeOnly?'checked':''}>Nur von mir vollständig markierte Tage berücksichtigen</label><div class="notice compact">${h.days} protokollierte Tage im Zeitraum berücksichtigt, davon ${h.completeDays} als vollständig markiert. Datenlücken in Nährstoffangaben bleiben sichtbar.</div><div class="summary-grid">${metric(h.average,'energy','Ø Energie','kcal',true)}${metric(h.average,'protein','Ø Protein','g')}${metric(h.average,'carbs','Ø Kohlenhydrate','g')}${metric(h.average,'fat','Ø Fett','g')}</div><div class="card"><h2>Energie pro erfasstem Tag</h2>${h.days?`<div class="history-chart" role="img" aria-label="Energie pro protokolliertem Tag; genaue Werte in der folgenden Tabelle">${h.rows.map(r=>`<div class="bar-col" title="${r.date}: ${val(r.n,'energy',0)} kcal"><div class="bar" style="height:${Math.max(2,(r.n.energy.value||0)/max*145)}px"></div><small>${r.date.slice(8)}.${r.date.slice(5,7)}</small></div>`).join('')}</div><div class="history-list"><div class="history-row head"><span>DATUM</span><span>ENERGIE</span><span>PROTEIN</span><span>PROTOKOLL</span></div>${h.rows.map(r=>`<div class="history-row"><button data-action="show-day" data-date="${r.date}">${r.date.slice(8)}.${r.date.slice(5,7)}.${r.date.slice(0,4)}</button><span>${val(r.n,'energy',0)} kcal</span><span>${val(r.n,'protein')} g</span><span>${r.complete?'Vollständig':'Unvollständig'}</span></div>`).join('')}</div>`:'<div class="empty"><p>Noch keine protokollierten Tage in diesem Zeitraum.</p></div>'}</div><div class="grid two-col spaced"><div class="card"><h2>Ø Vitamine / erfasster Tag</h2>${nutrientTable(h.average,'vitamin',true)}</div><div class="card"><h2>Ø Mineralstoffe / erfasster Tag</h2>${nutrientTable(h.average,'mineral',true)}</div></div>`;}
function profileView(){const p=state.profile,refs=targetSet();return heading('Dein persönlicher Kompass.','Nur die Angaben, die du für deine Auswertung verwenden möchtest.',btn(ico('download')+' Datensicherung','export','secondary'),'PROFIL & EINSTELLUNGEN')+`<div class="grid two-col"><section><form id="profile-form" class="card">${window.NK_MACRO_UI.controls(p)}${window.NK_REPORT_UI.controls(p)}<h2>Körperdaten & Referenzprofil</h2><div class="form-grid">${numField('age','Alter · Jahre',p.age,'Automatische Referenzen ab 19 Jahren.','inputmode="numeric"')}<div class="field"><label for="sex">Geschlecht für Referenzwerte</label><select id="sex">${options([['','Keine Auswahl'],['m','Männlich'],['w','Weiblich']],p.sex)}</select><small>Bezieht sich auf die Tabellenbasis, nicht auf deine Identität.</small></div>${numField('weight','Körpergewicht · kg',p.weight)}${numField('height','Körpergrösse · cm',p.height)}</div><label class="check"><input type="checkbox" id="special" ${p.special?'checked':''}><span>Besondere Situation: z. B. Schwangerschaft, Stillzeit, Nierenerkrankung, Essstörung oder andere medizinisch angepasste Ernährung.<br><span class="tiny">Automatische Ziele werden dann ausgesetzt. Eigene fachlich abgestimmte Ziele bleiben möglich.</span></span></label><label class="check"><input type="checkbox" id="smoker" ${p.smoker?'checked':''}><span>Raucherprofil für den Vitamin-C-Referenzwert berücksichtigen.</span></label><details class="details-section"><summary>Weitere Referenz-Einstellungen</summary><div class="form-grid">${numField('calc-weight','Protein-Berechnungsgewicht · kg',p.calcWeight,'Optional, fachlich abstimmen. Ausserhalb eines BMI von 18,5–25 wird das aktuelle Gewicht nicht automatisch verwendet.')}<div class="field"><label for="menopause">Eisen-Referenz bei weiblichem Profil</label><select id="menopause">${options([['','Nicht angegeben'],['pre','Prämenopausal'],['post','Postmenopausal']],p.menopause)}</select></div><div class="field full"><label for="phytate">Phytatzufuhr für Zink</label><select id="phytate">${options([['','Nicht eingeschätzt – keinen Einzelwert zeigen'],['low','Niedrig'],['medium','Mittel'],['high','Hoch']],p.phytate)}</select><small>Niedrig: wenig Vollkorn/Hülsenfrüchte, vor allem tierische Proteinquellen. Mittel: gemischte Ernährung bzw. vermehrt gekeimte/fermentierte Getreideprodukte. Hoch: viel nicht gekeimtes Vollkorn und Hülsenfrüchte, vorwiegend pflanzliche Proteinquellen. Diese Auswahl ist deine Einschätzung, keine Messung.</small></div></div></details><div class="form-section"><h3>Eigene Tagesziele · optional</h3><p class="small">Eigene Werte ersetzen die berechneten Ziele, auch nach Wechsel des Ernährungsziels. Leer lassen = Automatik. Energiebedarf und Zielanpassungen sind Schätzungen, keine Messungen.</p><div class="form-grid">${numField('target-energy','Energie · kcal',p.manual.energy)}${numField('target-protein','Protein · g',p.manual.protein)}${numField('target-carbs','Kohlenhydrate · g',p.manual.carbs)}${numField('target-fat','Fett · g',p.manual.fat)}</div><details class="details-section"><summary>Weitere eigene Nährstoffziele</summary><div class="form-grid">${NS.filter(n=>!['energy','protein','carbs','fat'].includes(n.key)&&n.group!=='other').map(n=>numField('target-'+n.key,esc(n.label)+' · '+n.unit,p.manual[n.key])).join('')}</div></details></div><section id="macro-preview" class="form-section" aria-live="polite"></section>${window.NK_MACRO_UI.sources()}<div id="profile-error"></div><button class="button wide spaced" type="submit">${ico('check')} Profil speichern</button></form><div class="card"><h2>Daten gehören dir.</h2><p class="small">Profil, Gerichte, eigene Produkte und Tagebuch werden geschützt bei Supabase gespeichert. Ausstehende Änderungen werden auf diesem Gerät verschlüsselt zwischengespeichert. Achte vor dem Schliessen auf den Status «Synchronisiert». Der gemeinsame Zugang kann alle Haushaltsprofile öffnen.</p><div class="actions">${btn(ico('download')+' Sicherung exportieren','export','secondary')}${btn(ico('upload')+' Sicherung importieren','import','secondary')}${btn('Tagebuch als CSV','csv','secondary')}</div>${storageBlocked?btn('Rohdaten sichern','export-raw','secondary spaced'):''}<p class="tiny spaced">Die JSON-Sicherung enthält deine persönlichen Einträge. Bewahre sie geschützt auf. Ein Import ersetzt nach Bestätigung den aktuellen Datenstand.</p>${btn(ico('trash')+' Aktuelles Profil leeren','delete-all','danger')}</div></section><aside><div class="card"><div class="card-head"><h2>Deine Vergleichswerte</h2>${ico('compass')}</div><p class="small">Gespeicherte Werte: Makroziele aus dem gewählten App-Plan, übrige DGE/ÖGE-Referenzen unverändert. Vitamine werden nicht pauschal mit dem Körpergewicht hochgerechnet.</p>${refs.notes.map(n=>`<div class="notice">${esc(n)}</div>`).join('')}<div class="small">${Object.entries(refs.values).filter(([k])=>['energy','protein','carbs','fat','vitC','magnesium','calcium','vitB12','vitD'].includes(k)).map(([k,r])=>`<div class="source-item"><strong>${esc(NS.find(n=>n.key===k)?.label)}: ${fmt(r.value)} ${NS.find(n=>n.key===k)?.unit}</strong>${r.type}${r.note?'<br>'+esc(r.note):''}</div>`).join('')}</div></div><div class="card"><h2>Auf dem Handy installieren</h2><p class="small"><b>Android:</b> Die veröffentlichte HTTPS-Adresse in Chrome öffnen und im Menü «App installieren» oder «Zum Startbildschirm hinzufügen» wählen.</p><p class="small"><b>iPhone:</b> Die HTTPS-Adresse in Safari öffnen → Teilen → «Zum Home-Bildschirm»; als Web-App öffnen, sofern angeboten.</p>${installPrompt?btn('Jetzt installieren','install','wide'):''}<p class="tiny">Eine lokal geöffnete HTML-Datei ist keine installierte PWA. Die App-Oberfläche wird offline vorgehalten. Erste Anmeldung, Produktabfragen und Synchronisierung benötigen Internet.</p></div><div class="card"><h2>Daten & Transparenz</h2><div class="source-item"><strong>${fmt(D.foods.length,0)} Lebensmittel · BLV 7.1</strong>Stand 01.07.2026 · Import ${esc(D.meta.importDate)}<br>${fmt(D.meta.counts.generic,0)} generische Lebensmittel + ${D.meta.counts.brand} Markenprodukte.<br><a href="${D.meta.url}" target="_blank" rel="noopener noreferrer">Offizielle Schweizer Nährwertdatenbank</a></div><p class="small spaced">${esc(D.meta.note)}</p><p class="small">Generische Angaben sind Durchschnittswerte, keine Analyse deiner konkreten Packung. Datenbank-Schätzungen bleiben als solche in den Quelldetails erkennbar.</p>${btn('Referenzquellen ansehen','sources','secondary wide')}<p class="tiny spaced">Version ${window.NK_DEVICE?.version||C.VERSION} · Packungsfoto, Barcode und passwortgeschützter Profilabgleich. Fotos werden nicht hochgeladen. Markenprodukte: <a href="https://world.openfoodfacts.org" target="_blank" rel="noopener noreferrer">Open Food Facts</a>, ODbL. Community-Daten bitte mit der Packung abgleichen.</p></div></aside></div>`;}
function showDialog(title,body){lastFocus=document.activeElement;const el=$('#dialog');el.innerHTML=`<div class="modal-head"><h2 id="dialog-title">${esc(title)}</h2>${ib('close','close-dialog','Schliessen')}</div>${body}`;if(!el.open)el.showModal();}
function closeDialog(){const d=$('#dialog');d.close();modal=null;lastFocus?.focus?.();}
function foodDialog(f,mode='log',replaceIndex=null){modal={type:'food',food:sourceFood(f),mode,replaceIndex};const existing=mode==='ingredient-edit'?draft.ingredients[replaceIndex]:null;modal.food=existing?copy(existing.food):modal.food;showDialog(existing?'Zutat anpassen':f.name,`<form id="food-form"><span class="source-badge">${esc(modal.food.source)}</span><p class="small spaced">Nährwerte beziehen sich auf 100 ${modal.food.basis}. Wähle deine tatsächliche Menge.</p><div class="amount-grid">${numField('food-qty','Menge',existing?.quantity??(modal.food.portion?1:100))}<div class="field"><label for="food-unit">Einheit</label><select id="food-unit">${options(unitOptions(modal.food),existing?.unit??(modal.food.portion?'piece':modal.food.basis))}</select></div></div><div class="piece-banner">${modal.food.portion?"<b>"+esc(P.label(modal.food))+"</b>":"Noch keine Stückportion hinterlegt."} ${btn(modal.food.portion?"Stückportion anpassen":"Stückportion hinterlegen","configure-portion","secondary")}<small>Nur essbarer Anteil, bei Eiern ohne Schale. Referenzgrössen sind geschätzt, nicht gewogen. Deine eigene Angabe hat Vorrang.</small></div>${pieceAmountFields(modal.food)}<details class="details-section" ${existing?.density?'open':''}><summary>Dichte / Umrechnung</summary>${numField('food-density','Dichte · g/ml',existing?.density??modal.food.density,'Nur erforderlich bei Umrechnung von Gewicht und Volumen. Ohne bekannte Dichte keine Gleichsetzung von ml und g.')}</details>${cupAmountFields(modal.food)}${mode==='log'?`<div class="form-grid spaced"><div class="field"><label for="food-date">Datum</label><input id="food-date" type="date" value="${date}"></div><div class="field"><label for="food-meal">Mahlzeit</label><select id="food-meal">${options(MEALS.map((x,i)=>[String(i),x]),String(window._NK_MEAL??1))}</select></div></div>`:''}<div id="food-preview" class="preview-box"></div><div id="modal-error"></div><details class="details-section"><summary>Alle Nährwerte & Quelle</summary><div id="food-all-nutrients"></div><p class="tiny spaced">${esc(f.category)} · Quelle ${esc(f.source)}${byId.has(f.id)?' · Lebensmittel-ID '+esc(f.id):''}</p>${byId.has(f.id)?btn('Herleitung der Originalwerte','food-provenance','secondary',`data-id="${esc(f.id)}"`):btn('Eigene Packungswerte bearbeiten','edit-custom-food','secondary',`data-id="${esc(f.id)}"`)}</details><div class="modal-foot"><button type="submit" class="button wide">${ico('plus')} ${mode==='log'?'Ins Tagebuch übernehmen':'Zutat übernehmen'}</button></div></form>`);updateFoodPreview();}
function updateFoodPreview(){if(modal?.type!=='food')return;try{const f=foodForCup(),s=C.snapshot(f,$('#food-qty').value,$('#food-unit').value,$('#food-density').value||null,KEYS);$('#food-preview').innerHTML=`<p class="piece-amount">${esc(describeAmount(f,$('#food-qty').value,$('#food-unit').value,$('#food-density').value||null))}</p><div class="preview-macros">${[['energy','kcal'],['protein','g Protein'],['carbs','g Kohlenhydrate'],['fat','g Fett']].map(([k,l])=>`<div><strong>${val(s,k,k==='energy'?0:1)}</strong><small>${l}</small></div>`).join('')}</div><p>* Bekannte Teilmenge bei fehlenden genauen Nährstoffangaben.</p>`;$('#food-all-nutrients').innerHTML=nutrientTable(s,'macro')+nutrientTable(s,'vitamin')+nutrientTable(s,'mineral');}catch(e){$('#food-preview').innerHTML=`<p class="error">${esc(e.message)}</p>`;}}
function ingredientSearch(index=null){readDraft();modal={type:'ingredient-search',index};showDialog(index===null?'Zutat hinzufügen':'Zutat austauschen',`<div class="searchbox">${ico('search')}<input id="ingredient-search" type="search" placeholder="Zutat suchen …" aria-label="Zutat suchen" autocomplete="off"></div><div class="small" id="ingredient-count"></div><div class="food-list" id="ingredient-results"></div><div class="modal-foot">${btn('Eigenes Produkt anlegen','ingredient-new-product','secondary')}</div>`);renderIngredientResults();}
function renderIngredientResults(){const el=$('#ingredient-results');if(!el)return;const arr=findFoods($('#ingredient-search').value);$('#ingredient-count').innerHTML=`${arr.length} Treffer · bis zu 40 angezeigt<br><br>`;el.innerHTML=foodRows(arr.slice(0,40),'ingredient');}
function logRecipeDialog(r){modal={type:'recipe',recipe:copy(r)};showDialog(r.name,`<form id="recipe-log-form"><p class="small">${r.ingredients.length} Zutaten · ${fmt(r.servings)} Portionen${r.finalWeight?' · '+fmt(r.finalWeight)+' g fertiges Gericht':''}</p><div class="amount-grid">${numField('log-qty','Gegessene Menge',1)}<div class="field"><label for="log-unit">Einheit</label><select id="log-unit">${options([['portion','Portionen'],...(r.finalWeight?[['g','g fertiges Gericht']]:[]),['batch','Gesamtes Gericht']],'portion')}</select></div></div><div class="form-grid spaced"><div class="field"><label for="log-date">Datum</label><input id="log-date" type="date" value="${date}"></div><div class="field"><label for="log-meal">Mahlzeit</label><select id="log-meal">${options(MEALS.map((x,i)=>[String(i),x]),String(window._NK_MEAL??1))}</select></div></div><div id="log-preview" class="preview-box"></div><p class="tiny spaced">Es wird eine Kopie der jetzt berechneten Werte gespeichert. Spätere Rezeptänderungen verändern diesen Eintrag nicht.</p><div id="modal-error"></div><div class="modal-foot"><button type="submit" class="button wide">${ico('plus')} Portion erfassen</button></div></form>`);updateLogPreview();}
function updateLogPreview(){if(modal?.type!=='recipe')return;try{$('#log-preview').innerHTML=mini(C.recipePortion(modal.recipe,$('#log-qty').value,$('#log-unit').value,KEYS))+(M.recipeEstimated(modal.recipe)?'<p class="measure-warning">Zutatenmengen teilweise geschätzt – Nährwerte entsprechend näherungsweise.</p>':'');}catch(e){$('#log-preview').innerHTML=`<p class="error">${esc(e.message)}</p>`;}}


function cupAmountFields(f){return `<section id="food-cup-fields" class="cup-fields" hidden><h3>Cups: Volumen ist nicht Gewicht</h3><p id="food-cup-explanation" class="small"></p>${referenceSelector(f,'cup')}<p id="food-cup-reference" class="measure-reference"></p>${numField('food-cup-grams','1 ausgewählte Cup dieser Zutat wiegt … g','','Bei fehlender Dichte wiegen oder eine geprüfte Umrechnung für genau diese Zutat verwenden. Keine pauschale Gleichsetzung von ml und g.')}<p class="tiny">Diese Angabe gilt für die Erfassung bzw. Rezeptzutat. Dauerhaft mit der Produktvorlage speichern: über den folgenden Button.</p>${btn("Cup-Gewicht im Produkt hinterlegen","configure-cup","secondary")}</section>`;}
function refreshCupAmountFields(){const unit=$('#food-unit')?.value,box=$('#food-cup-fields');if(!box||!modal?.food)return;box.hidden=!U.isCup(unit);if(box.hidden)return;const selected=$('#food-cup-kind')?.value;const f=selected&&selected!=='custom'?M.choose(modal.food,'cup',selected):modal.food,c=f.cup;const grams=$('#food-cup-grams');grams.closest('.field').hidden=f.basis==='ml';if(box.dataset.unit!==unit){const old=box.dataset.unit;grams.value=old&&grams.value.trim()?Number((C.positive(grams.value)*U.sizes[unit]/U.sizes[old]).toPrecision(12)):c?Number((c.grams*U.sizes[unit]/c.ml).toPrecision(12)):'';box.dataset.unit=unit;}$('#food-cup-explanation').textContent='1 ausgewählte Cup = '+fmt(U.sizes[unit],3)+' ml.'+(f.basis==='ml'?' Direkte Umrechnung zur Nährwertbasis pro 100 ml.':' Mehl, Öl und andere Zutaten wiegen bei gleichem Volumen unterschiedlich.');}
function foodForCup(){
 refreshCupAmountFields();refreshPieceFields();let f=copy(modal.food),u=$('#food-unit').value;
 if(u==='piece'){
  const pick=$('#food-piece-kind')?.value;if(pick&&pick!=='custom')f=M.choose(f,'piece',pick);
  const def={label:pick==='custom'&&M.options(f,'piece').length?(f.portion?.label||'Stück').split(' · ')[0]:(f.portion?.label||'Stück'),size:C.positive($('#food-piece-size').value),unit:f.basis};
  f.portion=pick==='custom'?def:M.preserve(def,f.portion,'piece');P.validate(f);const option=$('#food-unit option[value=piece]');if(option)option.textContent=P.units(f)[0][1];const banner=$('#food-form .piece-banner b');if(banner)banner.textContent=P.label(f);measureNotice(f,'piece');
 }
 if(U.isCup(u)&&f.basis==='g'){
  const pick=$('#food-cup-kind')?.value;if(pick&&pick!=='custom')f=M.choose(f,'cup',pick);
  if($('#food-cup-grams').value.trim())f.cup=M.preserve({grams:C.positive($('#food-cup-grams').value),ml:U.sizes[u]},pick==='custom'?null:f.cup,'cup');
  else f.cup=null;
  U.validate(f);measureNotice(f,'cup');
 }
 return f;
}
function referenceSelector(f,kind){const opts=M.options(f,kind);if(!opts.length)return '';const def=f[kind==='cup'?'cup':'portion'];return `<div class="field"><label for="food-${kind}-kind">${kind==='cup'?'Zustand / Füllweise':'Stückgrösse'} · Referenz oder eigene Angabe</label><select id="food-${kind}-kind">${options([...opts.map(v=>[v.id,v.label+' · ca. '+fmt(v.grams)+' g'+(kind==='cup'?' / 240 ml':'')]),['custom','Eigene Angabe / gewogen']],def?.estimated?def.reference.variantId:'custom')}</select></div>`;}
function pieceAmountFields(f){return `<section id="food-piece-fields" class="measure-fields" hidden><h3>Wie gross ist dein Stück?</h3>${referenceSelector(f,'piece')}${numField('food-piece-size','1 Stück entspricht … '+f.basis,f.portion?.size,'Für diese Erfassung überschreibbar. Essbaren Anteil ohne Abfall verwenden.')}<p id="food-piece-reference" class="measure-reference"></p></section>`;}
function refreshPieceFields(){const box=$('#food-piece-fields');if(box)box.hidden=$('#food-unit')?.value!=='piece';}
function measureNotice(f,kind){const el=$('#food-'+kind+'-reference');if(!el)return;const def=f[kind==='cup'?'cup':'portion'];el.textContent=def?.estimated?M.explanation(f,kind)+(kind==='cup'?' Volumen-/Schüttdichte näherungsweise '+fmt(def.grams/def.ml,3)+' g/ml. Gleiche Schnittform und Füllweise vorausgesetzt.':''):'Eigene Gewichtsangabe. Sie gilt für diese Erfassung; dauerhaft über die Produktvorlage speichern.';if(def?.estimated&&/^https:\/\/(?:fdc.nal.usda.gov|www.kingarthurbaking.com)\//.test(def.reference?.sourceUrl||'')){const a=document.createElement('a');a.href=def.reference.sourceUrl;a.target='_blank';a.rel='noopener noreferrer';a.textContent=def.reference.sourceName;el.append(document.createElement('br'),a);}}
function chooseMeasure(kind){const sel=$('#food-'+kind+'-kind');if(!sel||sel.value==='custom'){updateFoodPreview();return;}const f=M.choose(modal.food,kind,sel.value);if(kind==='piece')$('#food-piece-size').value=f.portion.size;else $('#food-cup-grams').value=Number((f.cup.grams*U.sizes[$('#food-unit').value]/f.cup.ml).toPrecision(12));updateFoodPreview();}

function customCupFields(f){return `<details class="details-section cup-fields" ${f?.cup?'open':''}><summary>Cups · optionale Gewichtsangabe</summary>${f?.cup?.estimated?'<p class="measure-warning">'+esc(M.explanation(f,'cup'))+'</p>':''}<p class="small">Für Produkte pro 100 g: Gewicht einer gefüllten Cup ohne Gefäss hinterlegen. Bei Angaben pro 100 ml ist keine Gewichtsangabe nötig.</p><div class="form-grid"><div class="field"><label for="custom-cup-type">Cup-Grösse der Referenz / gewogenen Portion</label><select id="custom-cup-type">${options(U.units,Object.keys(U.sizes).find(k=>U.sizes[k]===f?.cup?.ml)||'cup240')}</select></div>${numField('custom-cup-grams','1 Cup wiegt … g',f?.cup?.grams,'Leer lassen, um eine gespeicherte Cup-Gewichtsangabe zu entfernen.')}</div><p class="tiny">Cup-Grösse prüfen: Küche 240 ml, metrisch 250 ml, US customary ca. 236,6 ml. Umrechnen in Gramm nur über die Zutat. Quellen: <a href="https://www.nist.gov/pml/owm/metric-si/metric-kitchen/metric-kitchen-cooking-measurement-equivalencies" target="_blank" rel="noopener noreferrer">NIST Küchenmasse</a>.</p></details>`;}
function readCustomCup(){const grams=C.number($('#custom-cup-grams').value,{optional:true,min:.000001,max:100000});if(grams===null)return null;const cup={grams,ml:U.sizes[$('#custom-cup-type').value]};U.validate({basis:$('#custom-basis').value,cup});return M.preserve(cup,modal?.food?.cup,'cup');}
function acceptRecipeImport(r,expectedId){if(window.NK_HOUSEHOLD?.id!==expectedId||mutationBusy)throw Error('Profil gewechselt oder Speichern läuft. Bitte erneut öffnen.');if(dirty&&!confirm('Ungespeicherten Rezeptentwurf durch das hineinkopierte Rezept ersetzen?'))return false;const check=C.initial();check.recipes=[r];C.validateState(check,KEYS);newRecipe(r);dirty=true;notify('Rezept als Entwurf übernommen. Prüfen und «Gericht speichern» drücken.');return true;}

function customPortionFields(f){return `<section class="piece-fields"><h3>Stückportion · optional</h3>${f?.portion?.estimated?'<p class="measure-warning">'+esc(M.explanation(f,'piece'))+'</p>':''}<p class="small">Einmal festlegen, dann Stückzahlen statt Gramm eintippen. Zum Beispiel Stück, Scheibe, Riegel oder Becher.</p><div class="form-grid"><div class="field"><label for="custom-piece-label">Bezeichnung für 1 Stück</label><input id="custom-piece-label" maxlength="40" value="${esc(f?.portion?.label||'Stück')}" placeholder="Stück"></div>${numField('custom-piece-size','1 Stück entspricht …',f?.portion?.size,'Wiegen oder von der Packung übernehmen.','placeholder="z. B. 50"')}<div class="field"><label for="custom-piece-unit">Einheit der Stückgrösse</label><select id="custom-piece-unit">${options([['g','g'],['ml','ml']],f?.portion?.unit||f?.basis||'g')}</select></div></div><div id="custom-piece-preview" class="small" role="status"></div><p class="tiny">Passend zur Nährwertbasis: g bei Angaben pro 100 g, ml bei Angaben pro 100 ml. Keine automatische Gleichsetzung. Ohne Verpackung / Schale wiegen. Menge leer lassen, um die Stückportion zu entfernen.</p></section>`;}
function readCustomPortion(){const size=C.number($('#custom-piece-size').value,{optional:true,min:.000001,max:100000});if(size===null)return null;const portion={label:$('#custom-piece-label').value.trim(),size,unit:$('#custom-piece-unit').value};P.validate({basis:$('#custom-basis').value,portion});return M.preserve(portion,modal?.food?.portion,'piece');}
function updateCustomPortionPreview(){const el=$('#custom-piece-preview');if(!el)return;try{const portion=readCustomPortion();if(!portion){el.textContent='Noch keine Stückgrösse – Angaben bleiben pro 100 g/ml.';return;}const f={portion,basis:$('#custom-basis').value};const details=[['energy','kcal'],['protein','g Protein'],['carbs','g Kohlenhydrate'],['fat','g Fett']].map(([k,u])=>{const n=C.number($('#custom-'+k).value,{optional:true});return n===null?null:fmt(n*portion.size/100)+' '+u;}).filter(Boolean);el.textContent=P.label(f)+(details.length?' · '+details.join(' · '):'');}catch(e){el.textContent=e.message;}}
function openCustomText(textOnly=true){const m=modal,form=$('#custom-food-form'),profileId=window.NK_HOUSEHOLD?.id;if(!form||m?.type!=='custom-food')return;window.NK_SCANNER.open({textOnly,name:$('#custom-name').value,onTransfer:f=>{if(modal!==m||!form.isConnected||profileId!==window.NK_HOUSEHOLD?.id)throw Error('Das Produktformular wurde gewechselt. Bitte erneut öffnen.');for(const n of NS)$('#custom-'+n.key).value=f.n[n.key]??'';$('#custom-name').value=f.name;$('#custom-basis').value=f.basis;m.food={...(m.food||{}),id:m.food?.id||f.id,source:f.source,sourceUrl:f.sourceUrl||null,q:copy(f.q||{})};$('#modal-error').innerHTML='<p class="small">Produktwerte übernommen. Noch nicht gespeichert. Stückportion und Werte prüfen, dann Produkt speichern.</p>';updateCustomPortionPreview();}});}

function customFoodDialog(existing=null,returnIngredient=false){if(existing?.shared){existing=copy(existing);existing.id='custom-'+uid();existing.name+=' · Variante';delete existing.shared;}modal={type:'custom-food',food:existing?copy(existing):null,returnIngredient};const f=existing;showDialog(existing?'Packungswerte bearbeiten':'Eigenes Produkt',`<form id="custom-food-form"><div class="text-import-launch"><b>Nährwerte nicht abtippen</b><p class="small">Kopierte Nährwerttabelle auslesen, Bezugsmenge prüfen und übernehmen. Name und Stückportion bleiben erhalten; die Tabelle ersetzt die Nährwertfelder erst nach deiner Bestätigung.</p>${btn("Nährwerttext auslesen","custom-text","secondary")} ${btn("Foto: Produkt oder Nährwerte","custom-photo","secondary")}</div><div class="form-grid"><div class="field full"><label for="custom-name">Produktname / Marke</label><input id="custom-name" maxlength="240" value="${esc(f?.name)}" required placeholder="Zum Beispiel meine Proteinmilch"></div><div class="field"><label for="custom-basis">Nährwertangaben pro</label><select id="custom-basis">${options([['g','100 g'],['ml','100 ml']],f?.basis||'g')}</select></div>${numField('custom-density','Dichte · g/ml (optional)',f?.density)}</div>${customPortionFields(f)}${customCupFields(f)}<div class="notice">Übernimm die Werte von der Packung in der angezeigten Einheit. Leere Felder bleiben <b>unbekannt</b>. Nur eine ausdrücklich angegebene Null als 0 eintragen.</div><div class="form-grid">${NS.filter(n=>n.group==='macro').map(n=>numField('custom-'+n.key,esc(n.label)+' · '+n.unit,f?.n[n.key])).join('')}</div><details class="details-section"><summary>Vitamine, Mineralstoffe und weitere Werte</summary><p class="tiny">Vitamin A nur als RAE, Vitamin E nur als RRR-α-Tocopherol und Niacin nur als Äquivalente in die entsprechend beschrifteten Felder eintragen. Eine Packungsangabe ohne passende Bezugsform nicht ungeprüft übernehmen. 1 mg = 1000 µg.</p><div class="form-grid">${NS.filter(n=>n.group!=='macro').map(n=>numField('custom-'+n.key,esc(n.label)+' · '+n.unit,f?.n[n.key])).join('')}</div></details><div id="modal-error"></div><div class="modal-foot">${f&&state.foods.some(x=>x.id===f.id)?btn('Produkt löschen','delete-custom','danger',`data-id="${f.id}"`):''}<button type="submit" class="button">${ico('check')} Produkt speichern</button></div></form>`);updateCustomPortionPreview();}
function entryMenu(e){modal={type:'entry',entry:copy(e)};showDialog(e.name,`<form id="entry-edit-form"><p class="small">${esc(e.amountText)} · ${val(e.n,'energy',0)} kcal · ${val(e.n,'protein')} g Protein</p><div class="form-grid">${numField('entry-factor','Menge relativ zum jetzigen Eintrag',1,'Zum Beispiel 0,5 für die Hälfte oder 2 für die doppelte Menge.')}<div class="field"><label for="entry-date">Datum</label><input id="entry-date" type="date" value="${e.date}"></div><div class="field full"><label for="entry-meal">Mahlzeit</label><select id="entry-meal">${options(MEALS.map((x,i)=>[String(i),x]),String(e.meal))}</select></div></div><div id="modal-error"></div><div class="modal-foot">${btn(ico('trash')+' Löschen','delete-entry','danger',`data-id="${e.id}"`)}${btn(ico('copy')+' Kopie für diesen Tag','duplicate-entry','secondary',`data-id="${e.id}"`)}<button type="submit" class="button">Speichern</button></div></form>`);}
function infoDialog(key){const n=NS.find(n=>n.key===key),ref=targetSet().values[key];let s=route==='history'?C.history(state,date,historyDays,KEYS,completeOnly).average:sumToday();if(route==='editor'&&draft?.ingredients.length){try{s=C.recipePortion(draft,1,'portion',KEYS);}catch{}}let a=s[key];showDialog(n.label,`<p><b>${val(s,key,2)} ${n.unit}</b> ${route==='editor'?'pro Rezeptportion':route==='history'?'im Durchschnitt der erfassten Tage':'im ausgewählten Tagebuch-Tag'}</p><p class="small">${a?.total?`${a.known} von ${a.total} Zutaten haben einen genauen Zahlenwert.`:'Noch keine erfassten Zutaten.'}</p>${a?.missing?.length?`<div class="notice warm"><b>Keine genaue Zahl hinterlegt für:</b><br>${a.missing.map(esc).join('<br>')}<br>Diese Angaben werden nicht als null behandelt. Sichtbare Summen können daher nur eine bekannte Teilmenge sein.</div>`:''}${ref?`<h3>${ref.type}</h3><p class="small">${fmt(ref.value)} ${n.unit} pro Tag. ${esc(ref.note)}<br>${ref.url?`${esc(ref.sourceLabel||'DGE/ÖGE')} · Quellenstand ${ref.year}, geprüft am 26.09.2026.<br><a href="${ref.url}" target="_blank" rel="noopener noreferrer">Referenzquelle öffnen</a>`:''}</p>`:'<p class="small">Für dieses Profil bzw. diesen Nährstoff ist kein automatischer Vergleich aktiv. Im Profil sind eigene Ziele möglich.</p>'}<p class="tiny">Eine rechnerische Zufuhr unter einem Referenzwert ist keine Mangeldiagnose. Ein Wert über 100 % ist keine automatische Gefahrenbewertung.</p>`);}
function sourcesDialog(){const slugs=['protein','vitamin-a','vitamin-c','vitamin-d','vitamin-e','thiamin','riboflavin','niacin','pantothensaeure','vitamin-b6','vitamin-b12','folat','calcium','magnesium','kalium','phosphor','eisen','zink','jod','selenium'];showDialog('Quellen & Berechnungsregeln',`<p class="small">Lebensmitteldaten: ${esc(D.meta.name)}, Version ${D.meta.version}. Import umfasst exakt ${D.foods.length} eindeutige Lebensmittel-IDs aus dem offiziellen Excel-Download.</p><p class="small"><a href="${D.meta.url}" target="_blank" rel="noopener noreferrer">BLV: Download und Nutzungsbedingungen</a></p><p class="tiny">Die Quellen-IDs und die Herleitung einzelner Werte sind über das jeweilige Lebensmittel abrufbar. Originaldatei und Importskript liegen im vollständigen Projektpaket.</p><h3>Referenzwerte</h3><p class="small">DGE/ÖGE, für gesunde Erwachsene ab 19 Jahren. Geprüft am 26.09.2026. Keine pauschale Gewichts-Skalierung der Vitamine. Bei gewähltem Ernährungsziel schätzt die App Tagesenergie und Makros; Rechenweg und Modellgrenzen stehen im Profil.</p>${slugs.map(s=>`<div class="source-item"><a href="https://www.dge.de/wissenschaft/referenzwerte/${s}/" target="_blank" rel="noopener noreferrer">DGE · ${esc(s.replace(/-/g,' '))}</a></div>`).join('')}<div class="notice">Folat: Der BLV-Download liefert Nahrungsfolat, der Referenzwert Folat-Äquivalente. Daher kein automatischer Prozentvergleich. Vitamin K und Biotin fehlen im BLV-Download; eigene Packungswerte können erfasst werden.</div><p class="small">Zubereitung: Die Werte der ausgewählten Zutaten werden addiert. Es gibt keine automatischen, unbestätigten Retentions- oder Kochverlustfaktoren. Wasserverlust verändert das Gewicht, nicht automatisch die Nährstoffsumme.</p>`);}
function provenance(id){const f=byId.get(id);if(!f)return;modal=null;showDialog('Quellen: '+f.name,`<p class="small">BLV 7.1 · ID ${esc(id)} · pro 100 ${f.basis}. «Schätzung» ist eine Kennzeichnung des offiziellen Datenbestands.</p>${NS.filter(n=>n.available).map(n=>{const p=f.provenance[n.key]||[],method=p[0]!==null&&p[0]!==undefined?D.methods[p[0]]:'',srcs=String(p[1]||'').split(';').filter(Boolean);return `<div class="source-item"><strong>${esc(n.label)}: ${f.n[n.key]===null?esc(f.q[n.key]||'Keine Angabe'):fmt(f.n[n.key],4)} ${n.unit}</strong>${esc(method||'Keine zusätzliche Herleitung angegeben')}${srcs.length?'<br>'+srcs.map(s=>esc(D.sources[s]||'Quellen-ID '+s)).join('<br>'):''}</div>`;}).join('')}`);}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function exportBackup(){download('Naehrstoff-Kompass-'+(window.NK_HOUSEHOLD?.name||'Profil')+'-Sicherung-'+C.dateKey()+'.json',JSON.stringify({...state,exportedAt:new Date().toISOString(),appVersion:C.VERSION},null,2));notify('Sicherung erstellt. Bitte die Datei geschützt aufbewahren.');}
function exportCSV(){const cells=x=>'"'+String(x??'').replace(/^[=+@-]/,c=>"'"+c).replace(/"/g,'""')+'"';const heads=['Datum','Mahlzeit','Name','Menge',...NS.flatMap(n=>[n.label+' ('+n.unit+')','Datenlage '+n.key])];const rows=state.entries.map(e=>[e.date,MEALS[e.meal]||'',e.name,e.amountText,...NS.flatMap(n=>[e.n[n.key].value??'',e.n[n.key].known+'/'+e.n[n.key].total])]);download('Naehrstoff-Kompass-Tagebuch.csv','\uFEFF'+[heads,...rows].map(r=>r.map(x=>cells(typeof x==='string'&&/^[=+@\-]/.test(x)?"'"+x:x)).join(';')).join('\r\n'),'text/csv;charset=utf-8');}
function readProfileForm(){const get=id=>$('#'+id).value,p=copy(state.profile);p.age=C.number(get('age'),{optional:true,min:0,max:120});if(p.age!==null&&!Number.isInteger(p.age))throw Error('Das Alter bitte in ganzen Jahren eingeben.');p.sex=get('sex');p.weight=C.number(get('weight'),{optional:true,min:1,max:600});p.height=C.number(get('height'),{optional:true,min:40,max:260});p.calcWeight=C.number(get('calc-weight'),{optional:true,min:1,max:600});p.special=$('#special').checked;p.smoker=$('#smoker').checked;p.menopause=get('menopause');p.phytate=get('phytate');p.manual=copy(state.profile.manual||{});for(const n of NS){const el=$('#target-'+n.key);if(el){const v=C.number(el.value,{optional:true,min:.000001});if(v!==null)p.manual[n.key]=v;else delete p.manual[n.key];}}p.reportFrequency=window.NK_REPORTS.checkFrequency(get('report-frequency'));p.goal=get('nutrition-goal');p.pal=C.number(get('activity-pal'),{optional:true,min:1.4,max:2.2});window.NK_MACROS.validate(p);return p;}
async function updateProfile(){const p=readProfileForm();await change(s=>s.profile=p);reportOptions=null;render();notify('Profil, Tagesziele und Report-Häufigkeit gespeichert.');}
function updateGoalPreview(){const el=$('#macro-preview');if(!el)return;try{const p=readProfileForm();const signature=JSON.stringify(p);if(el.dataset.goalPreview===signature)return;el.dataset.goalPreview=signature;$('#goal-description').textContent=window.NK_MACROS.PRESETS[p.goal]?.description||'Bestehende Protein-Basisreferenz und eigene Ziele bleiben unverändert. Wähle ein Zielprofil für die erweiterte automatische Berechnung.';el.innerHTML=window.NK_MACRO_UI.preview(p);}catch(e){delete el.dataset.goalPreview;el.innerHTML='<p class="small" role="status">Vorschau: '+esc(e.message)+'</p>';}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;if(mutationBusy)return;const a=b.dataset.action,id=b.dataset.id;try{
 if(a==='open-default-report'){reportOptions={frequency:window.NK_REPORTS.frequency(state.profile),anchor:b.dataset.date||C.dateKey(),completeOnly:false,filter:'all'};nav('reports');}
 else if(a==='report-expand-all'){getReportOptions().expanded=!getReportOptions().expanded;render();}
 else if(a==='report-period'){getReportOptions().frequency=window.NK_REPORTS.checkFrequency(b.dataset.frequency);render();}
 else if(a==='report-prev'||a==='report-next'){const o=getReportOptions(),p=window.NK_REPORTS.period(o.frequency,o.anchor),n=window.NK_REPORTS.adjacent(p,a==='report-prev'?-1:1);if(n.start<=C.dateKey()){o.anchor=n.start;render();}}
 else if(a==='report-current'){getReportOptions().anchor=C.dateKey();render();}
 else if(a==='report-previous-complete'){const o=getReportOptions();o.anchor=window.NK_REPORTS.previous(o.frequency).start;render();}
 else if(a==='report-pdf'){const r=window.NK_REPORTS.build(state,NS,getReportOptions());window.NK_REPORT_PDF.open(r,window.NK_HOUSEHOLD?.name||'Profil',{syncPending:!!window.NK_HOUSEHOLD?.pending});}
 else if(a==='report-export'){const r=window.NK_REPORTS.build(state,NS,getReportOptions());download('Kompass-Report-'+r.period.start+'-'+r.period.end+'.csv',window.NK_REPORTS.csv(r,window.NK_HOUSEHOLD?.name||'Profil'),'text/csv;charset=utf-8');notify('Report exportiert. Die Datei enthält persönliche Angaben.');}
 else if(a==='suggest-calc-weight'){const h=C.number($('#height').value,{min:130,max:220});$('#calc-weight').value=String(Math.round(window.NK_MACROS.referenceWeight(h)*10)/10);$('#calc-weight').closest('details').open=true;$('#calc-weight').dispatchEvent(new Event('input',{bubbles:true}));notify('Berechnungsgewicht eingesetzt. Bitte prüfen und Profil speichern.');}
 else if(a==='reset-macro-goals'){if(confirm('Eigene Ziele für Energie, Protein, Kohlenhydrate und Fett aus den Formularfeldern entfernen? Andere Nährstoffziele bleiben erhalten. Aktiv erst nach Profil speichern.')){for(const k of ['energy','protein','carbs','fat'])$('#target-'+k).value='';$('#target-energy').dispatchEvent(new Event('input',{bubbles:true}));}}
 else if(a==='shared-refresh'){await window.NK_SHARED?.refresh(true);notify(window.NK_SHARED?.status||'Katalog aktualisiert.');}
 else if(a==='paste-recipe')window.NK_RECIPE_IMPORT.open();
 else if(a==='custom-text')openCustomText();
 else if(a==='custom-photo')openCustomText(false);
 else if(a==='configure-cup'){const old=modal;let f=foodForCup();if(byId.has(f.id))f={...f,id:'custom-'+uid(),kind:'custom'};customFoodDialog(f,old.mode!=='log');modal.returnIndex=old.replaceIndex??null;$('#custom-cup-grams').closest('details').open=true;$('#custom-cup-grams').focus();}
 else if(a==='configure-portion'){const old=modal;let f=foodForCup();if(byId.has(f.id))f={...f,id:'custom-'+uid(),kind:'custom'};customFoodDialog(f,old.mode!=='log');modal.returnIndex=old.replaceIndex??null;$('#custom-piece-size').focus();}
 else if(a==='nav')nav(b.dataset.route);
 else if(a==='prev-day'||a==='next-day'){const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+(a==='prev-day'?-1:1));date=C.dateKey(d);render();}
 else if(a==='show-day'){date=b.dataset.date;nav('today');}
 else if(a==='add-meal'){window._NK_MEAL=Number(b.dataset.meal);nav('search');}
 else if(a==='filter'){filter=b.dataset.filter;render();}
 else if(a==='nutrient-tab'){nutrientTab=b.dataset.tab;render();}
 else if(a==='nutrient-info')infoDialog(b.dataset.key);
 else if(a==='favorite'){await change(s=>{s.favorites=s.favorites.includes(id)?s.favorites.filter(x=>x!==id):[...s.favorites,id];});if(modal?.type==='ingredient-search')renderIngredientResults();else renderSearchResults();}
 else if(a==='food-pick'){const ix=modal?.type==='ingredient-search'?modal.index:null;foodDialog(food(id),b.dataset.mode||'log',ix);}
 else if(a==='new-food')customFoodDialog();
 else if(a==='ingredient-new-product')customFoodDialog(null,true);
 else if(a==='edit-custom-food'){const f=food(id);customFoodDialog(f,route==='editor');}
 else if(a==='delete-custom'){if(confirm('Dieses eigene Produkt löschen? Gespeicherte Gerichte und bisherige Einträge behalten ihre Kopien.')){await change(s=>{s.foods=s.foods.filter(f=>f.id!==id);s.favorites=s.favorites.filter(x=>x!==id);});closeDialog();render();notify('Eigenes Produkt gelöscht.');}}
 else if(a==='new-recipe'){if(route!=='editor'||!dirty||confirm('Ungespeichertes Gericht verwerfen?'))newRecipe();}
 else if(a==='edit-recipe')newRecipe(recipe(id));
 else if(a==='duplicate-recipe')newRecipe(recipe(id),true);
 else if(a==='delete-recipe'){if(confirm('Gericht löschen? Bereits erfasste Mahlzeiten bleiben erhalten.'))await removeWithUndo(s=>s.recipes=s.recipes.filter(r=>r.id!==id),'Gericht gelöscht.');}
 else if(a==='ingredient-search')ingredientSearch();
 else if(a==='replace-ingredient')ingredientSearch(Number(b.dataset.index));
 else if(a==='ingredient-details'){readDraft();const ix=Number(b.dataset.index);foodDialog(draft.ingredients[ix].food,'ingredient-edit',ix);}
 else if(a==='remove-ingredient'){readDraft();draft.ingredients.splice(Number(b.dataset.index),1);dirty=true;render();}
 else if(a==='save-recipe'){mutationBusy=true;b.disabled=true;try{await saveRecipe();}finally{mutationBusy=false;b.disabled=false;}}
 else if(a==='save-variant'){mutationBusy=true;b.disabled=true;try{await saveRecipe(true);}finally{mutationBusy=false;b.disabled=false;}}
 else if(a==='log-recipe')logRecipeDialog(recipe(id));
 else if(a==='entry-menu')entryMenu(state.entries.find(x=>x.id===id));
 else if(a==='delete-entry'){closeDialog();await removeWithUndo(s=>s.entries=s.entries.filter(x=>x.id!==id),'Eintrag gelöscht.');}
 else if(a==='duplicate-entry'){const ent=state.entries.find(x=>x.id===id),newDate=$('#entry-date').value;if(!C.validDate(newDate))throw Error('Bitte ein gültiges Datum wählen.');const f=C.positive($('#entry-factor').value);await change(s=>s.entries.push({...copy(ent),id:uid(),date:newDate,meal:Number($('#entry-meal').value),n:C.scale(ent.n,f),...(U.scaledEntry(ent,f)||P.scaledEntry(ent,f))}));date=newDate;closeDialog();render();notify('Kopie erfasst.');}
 else if(a==='undo'&&undo){await persist(undo);undo=null;render();notify('Löschung rückgängig gemacht.');}
 else if(a==='history-period'){historyDays=Number(b.dataset.days);render();}
 else if(a==='close-dialog')closeDialog();
 else if(a==='food-provenance')provenance(id);
 else if(a==='sources')sourcesDialog();
 else if(a==='export')exportBackup();
 else if(a==='csv')exportCSV();
 else if(a==='export-raw')download('Naehrstoff-Kompass-Rohdaten.json',(window.NK_STORE||localStorage).getItem(KEY)||'{}');
 else if(a==='import')$('#backup-input').click();
 else if(a==='delete-all'){if(confirm('Alle Einträge, Gerichte und Einstellungen dieses Profils auch auf dem Server leeren? Andere Profile bleiben erhalten. Vorher eine Sicherung exportieren.')){await (window.NK_STORE||localStorage).removeItem(KEY);storageBlocked=false;storageProblem='';state=C.initial();draft=null;dirty=false;undo=null;render();notify('Persönliche Daten auf diesem Gerät gelöscht.');}}
 else if(a==='install'&&installPrompt){installPrompt.prompt();installPrompt=null;}
 }catch(error){showError(error.message);}});
function showError(text){const el=modal?$('#modal-error'):route==='editor'?$('#recipe-error'):$('#profile-error');if(el)el.innerHTML=`<div class="error" role="alert">${esc(text)}</div>`;else notify(text);}
document.addEventListener('input',e=>{const el=e.target;try{
 if(el.closest('#custom-food-form')){updateCustomPortionPreview();}
 else if(el.closest('#profile-form')){updateGoalPreview();}
 else if(el.id==='food-search'){search=el.value;renderSearchResults();}
 else if(el.id==='ingredient-search')renderIngredientResults();
 else if(el.id==='recipe-search'){recipeSearch=el.value;const start=el.selectionStart;render();$('#recipe-search').focus();$('#recipe-search').setSelectionRange(start,start);}
 else if(['recipe-name','recipe-servings','recipe-weight','recipe-notes'].includes(el.id)){readDraft();dirty=true;updateRecipeSummary();}
 else if(el.dataset.ingredient!==undefined){draft.ingredients[Number(el.dataset.ingredient)][el.dataset.field]=el.value;dirty=true;updateRecipeSummary();}
 else if(['food-qty','food-density','food-cup-grams','food-piece-size'].includes(el.id)){if(el.id==='food-cup-grams'&&$('#food-cup-kind'))$('#food-cup-kind').value='custom';if(el.id==='food-piece-size'&&$('#food-piece-kind'))$('#food-piece-kind').value='custom';updateFoodPreview();}
 else if(el.id==='log-qty')updateLogPreview();
 }catch(error){showError(error.message);}});
document.addEventListener('change',async e=>{const el=e.target;try{
 if(el.id==='report-date'||el.id==='report-history'){if(C.validDate(el.value)&&el.value<=C.dateKey()){getReportOptions().anchor=el.value;render();}else if(el.value)throw Error('Bitte ein Datum bis heute wählen.');}
 else if(el.id==='report-complete-only'){getReportOptions().completeOnly=el.checked;render();}
 else if(el.id==='report-filter'){getReportOptions().filter=el.value;render();}
 else if(el.closest('#custom-food-form')){updateCustomPortionPreview();}
 else if(el.closest('#profile-form')){updateGoalPreview();}
 else if(el.id==='diary-date'){if(C.validDate(el.value)){date=el.value;render();}}
 else if(el.id==='day-complete'){const day=date,complete=el.checked;await change(s=>s.days[day]={...s.days[day],complete});}
 else if(el.id==='complete-only'){completeOnly=el.checked;render();}
 else if(el.id==='food-cup-kind')chooseMeasure('cup');
 else if(el.id==='food-piece-kind')chooseMeasure('piece');
 else if(el.id==='food-unit'){refreshCupAmountFields();updateFoodPreview();}
 else if(el.id==='log-unit')updateLogPreview();
 else if(el.dataset.ingredient!==undefined){draft.ingredients[Number(el.dataset.ingredient)][el.dataset.field]=el.value;dirty=true;updateRecipeSummary();}
 }catch(error){showError(error.message);}});
document.addEventListener('submit',async e=>{if(!['profile-form','food-form','recipe-log-form','custom-food-form','entry-edit-form'].includes(e.target.id))return;e.preventDefault();if(mutationBusy)return;mutationBusy=true;const submitButtons=[...e.target.querySelectorAll('button[type=submit]')];submitButtons.forEach(b=>b.disabled=true);try{
 if(e.target.id==='profile-form'){await updateProfile();return;}
 if(e.target.id==='food-form'){
  const m=modal,operationId=m.operationId||(m.operationId=uid()),quantity=U.amount($('#food-qty').value),unit=$('#food-unit').value,density=C.number($('#food-density').value,{optional:true,min:.000001,max:100});const selected=foodForCup(),n=C.snapshot(selected,quantity,unit,density,KEYS);
  if(m.mode==='log'){const dt=$('#food-date').value;if(!C.validDate(dt))throw Error('Bitte ein gültiges Datum wählen.');const meal=Number($('#food-meal').value);await change(s=>{s.entries=s.entries.filter(e=>e.id!==operationId);s.entries.push({id:operationId,date:dt,meal,name:m.food.name,kind:'food',...(U.isCup(unit)?U.entryAmount(selected,quantity,unit,density):P.entryAmount(selected,quantity,unit)),n,createdAt:new Date().toISOString(),sourceId:m.food.id});s.recent=[m.food.id,...s.recent.filter(x=>x!==m.food.id)].slice(0,30);});date=dt;closeDialog();route='today';render();notify('Lebensmittel erfasst.');}
  else{const item={food:selected,quantity,unit,density};if(m.replaceIndex!==null&&m.replaceIndex!==undefined)draft.ingredients[m.replaceIndex]=item;else draft.ingredients.push(item);dirty=true;closeDialog();render();notify('Zutat übernommen.');}
 }else if(e.target.id==='recipe-log-form'){
  const operationId=modal.operationId||(modal.operationId=uid()),r=modal.recipe,amount=C.positive($('#log-qty').value),unit=$('#log-unit').value,n=C.recipePortion(r,amount,unit,KEYS),dt=$('#log-date').value,meal=Number($('#log-meal').value);if(!C.validDate(dt))throw Error('Bitte ein gültiges Datum wählen.');await change(s=>{s.entries=s.entries.filter(e=>e.id!==operationId);s.entries.push({id:operationId,date:dt,meal,kind:'recipe',name:r.name,amountText:fmt(amount)+' '+(unit==='portion'?'Portion(en)':unit==='g'?'g fertiges Gericht':'× gesamtes Gericht')+(M.recipeEstimated(r)?' · Zutatenmengen geschätzt':''),n,recipeId:r.id,recipeVersion:r.version,ingredients:copy(r.ingredients),createdAt:new Date().toISOString()});});date=dt;closeDialog();route='today';render();notify('Gericht erfasst.');
 }else if(e.target.id==='custom-food-form'){
  const m=modal,n={};for(const field of NS)n[field.key]=C.number($('#custom-'+field.key).value,{optional:true});const f={id:m.food?.id||(m.operationId||(m.operationId='custom-'+uid())),name:$('#custom-name').value.trim(),basis:$('#custom-basis').value,density:C.number($('#custom-density').value,{optional:true,min:.000001,max:100}),n,q:Object.fromEntries(Object.entries(m.food?.q||{}).filter(([k])=>n[k]===null)),kind:'custom',source:m.food?.source||'Eigene Packungsangaben',sourceUrl:m.food?.sourceUrl||null,synonyms:'',category:'Eigene Produkte',portion:readCustomPortion(),cup:readCustomCup()};C.validateFood(f,KEYS);if(!NS.some(x=>n[x.key]!==null))throw Error('Bitte mindestens einen Nährwert eintragen.');await change(s=>{s.foods=s.foods.filter(x=>x.id!==f.id);s.foods.unshift(f);});closeDialog();if(m.returnIngredient)foodDialog(f,'ingredient',m.returnIndex??null);else{route='search';filter='custom';search='';render();notify('Eigenes Produkt gespeichert.');}
 }else if(e.target.id==='entry-edit-form'){
  const ent=modal.entry,f=C.positive($('#entry-factor').value),dt=$('#entry-date').value,meal=Number($('#entry-meal').value);if(!C.validDate(dt))throw Error('Bitte ein gültiges Datum wählen.');await change(s=>{const i=s.entries.findIndex(x=>x.id===ent.id);s.entries[i]={...ent,date:dt,meal,n:C.scale(ent.n,f),...(U.scaledEntry(ent,f)||P.scaledEntry(ent,f))};});date=dt;closeDialog();render();notify('Eintrag aktualisiert.');
 }
 }catch(error){showError(error.message);}finally{mutationBusy=false;submitButtons.forEach(b=>b.disabled=false);}});
$('#backup-input').addEventListener('change',async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;try{if(f.size>15*1024*1024)throw Error('Sicherungsdatei ist zu gross (maximal 15 MB).');const parsed=JSON.parse(await f.text());const next=C.validateState(parsed,KEYS);if(confirm(`Sicherung mit ${next.entries.length} Einträgen, ${next.recipes.length} Gerichten und ${next.foods.length} eigenen Produkten importieren? Der aktuelle Datenstand wird ersetzt.`)){const oldBlocked=storageBlocked;storageBlocked=false;try{await persist(next);}catch(err){storageBlocked=oldBlocked;throw err;}dirty=false;draft=null;undo=null;render();reportOptions=null;render();notify('Sicherung importiert.');}}catch(error){notify('Import nicht durchgeführt: '+error.message);}});
$('#dialog').addEventListener('cancel',()=>{modal=null;});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;if(route==='profile')render();});
window.addEventListener('storage',e=>{if(e.key===KEY){storageProblem='Daten wurden in einem anderen Fenster geändert. Bitte diese Seite neu laden, bevor du weitere Änderungen speicherst.';notify(storageProblem);storageBlocked=true;}});
if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(()=>{});
render();
// Deliberately expose only calculation metadata for automated local UI smoke tests.
window.NK_APP={respondDayReview,openDay,acceptRecipeImport,acknowledgeReleases,version:C.VERSION,foodCount:D.foods.length,reviewFood:f=>customFoodDialog(f),openFood:f=>foodDialog(f),refresh:render,get hasDraft(){return dirty||mutationBusy||!!window.NK_RECIPE_IMPORT?.hasDraft;},acceptSyncState:s=>{state=C.validateState(s,KEYS);storageProblem='';storageBlocked=false;undo=null;if(!dirty&&!modal&&!mutationBusy&&route!=='profile')render();},refreshCatalog:()=>{if(route==='search'&&!modal)renderSearchResults();if(route==='recipes')render();if(modal?.type==='ingredient-search')renderIngredientResults();},canSwitch:()=>{if(mutationBusy){notify('Bitte warten, bis der Speichervorgang abgeschlossen ist.');return false;}return !(dirty||window.NK_RECIPE_IMPORT?.hasDraft||window.NK_DEVICE?.hasUnsavedForm())||confirm('Ungespeicherte Eingaben verwerfen und Profil wechseln?');},loadState:s=>{reportOptions=null;state=C.validateState(s,KEYS);storageBlocked=false;storageProblem='';dirty=false;draft=null;undo=null;route='today';closeDialog();render();},clearState:()=>{reportOptions=null;state=C.initial();dirty=false;draft=null;undo=null;modal=null;document.querySelector('#app').innerHTML='';},getState:()=>copy(state)};
})();
